// Copy mPSE for the outer object so deepFreeze does not freeze the caller's original.
const frozenMPSE = deepFreeze({ ...base.mPSE });
return deepFreeze({ ...base, mPSE: frozenMPSE, state: base.verdict, triplet: frozenMPSE });

const deepFreeze = <T>(o: T, seen = new WeakSet<object>()): T => {
  if (o !== null && typeof o === 'object' && !seen.has(o)) {
    seen.add(o);
    for (const v of Object.values(o as Record<string, unknown>)) deepFreeze(v, seen);
    Object.freeze(o);
  }
  return o;
};

